"""Step-decomposed rewrites of RE-ARC solver programs (verifiers).

Every function below keeps the exact input -> output behavior of the upstream
verify_<id> in verifiers.py, but restructures the computation so that the grids
assigned along the way form a sequence of semantic solving stages in output
dimensions, aligned with the per-task step annotations of the ARC-GEN
generators for the same puzzle. rearc_steps.load_verifier_trees overlays these
functions on verifiers.py; by default (--steps-from rewritten) only the tasks
rewritten here emit steps, and a per-sample consistency gate (traced return
value == stored output) checks every rewrite across the whole dataset.

Straight-line constraint: single-target assignments and one return.
Unrolling convention for variable-count stages: k ranked stages via the
min/remove/sentinel-insert chain (exhausted ranks repaint the last element,
which dedups as a no-op) plus one final catch-all stage that applies the full
union, so the returned grid always equals the upstream verifier's.
Marker-color rule: a marker color introduced by a stage must avoid the input
palette (prefer the reference color, else a deterministic fallback).
OFFDIM_TASKS lists the tasks whose reference stages are deliberately not in
output dimensions (e.g. a denoised input or a bordered window); their
off-dimension frames are kept by rearc_steps.
"""
from dsl import *

OFFDIM_TASKS = {"1190e5a7", "1c786137", "1fad071e", "239be575", "23b5c85d", "39a8645d", "3f7978a0", "445eab21", "48d8fb45", "5117e062", "5614dbcf", "5ad4f10b", "5bd6f4ac", "662c240a", "6773b310", "67e8384a", "746b3537", "7837ac64", "995c5fa3", "9ecd008a", "9f236235", "b0c4d837", "b9b7f026", "c3e719e8", "cce03e0d", "d9fac9be", "dc0a314f", "de1cd16c", "eb281b96", "f8b3ba0a", "f9012d9b", "ff28f65a", "ff805c23"}


